// Command generate-event-types publishes the core event-type vocabulary from
// the descriptor table in sdk/event, and gates it.
//
// It writes two artefacts. Do not edit them by hand:
//
//	docs/vocabularies/event-types.json      the machine-readable set
//	docs/src/content/docs/event-types.md    the reference a consumer reads
//
// A committed type the code does not declare fails the run unless
// -allow-removals is set, because a consumer may still use it. With -check it
// writes nothing and fails when a committed artefact differs from the
// generated one.
//
// Run via: make generate-event-types, gated by make event-types-check.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"

	"github.com/prusa3d/prusa-connect/internal/codegen"
	"github.com/prusa3d/prusa-connect/sdk/event"
)

const (
	defaultCataloguePath = "docs/vocabularies/event-types.json"
	defaultReferencePath = "docs/src/content/docs/event-types.md"

	// generatedNotice is the first thing in both artefacts.
	generatedNotice = "Generated by 'make generate-event-types' from the descriptor table in sdk/event. " +
		"Do not edit: change the table in Go and regenerate."
)

type options struct {
	cataloguePath string
	referencePath string
	check         bool
	allowRemovals bool
}

func main() {
	opts := options{}

	flag.StringVar(&opts.cataloguePath, "catalogue", defaultCataloguePath,
		"path of the machine-readable event-type set")
	flag.StringVar(&opts.referencePath, "reference", defaultReferencePath,
		"path of the published event-type reference")
	flag.BoolVar(&opts.check, "check", false,
		"compare the committed artefacts against the generated ones and write nothing")
	flag.BoolVar(&opts.allowRemovals, "allow-removals", false,
		"let a type disappear. A consumer is still routing on it: for a deliberate retirement in a "+
			"breaking release only")
	flag.Parse()

	if err := run(event.TypeDocs(), opts); err != nil {
		fmt.Fprintf(os.Stderr, "generate-event-types: %v\n", err)
		os.Exit(1)
	}
}

func run(entries []event.TypeDoc, opts options) error {
	committed, err := codegen.ReadCatalogue[catalogueFile](opts.cataloguePath)
	if err != nil {
		return err
	}

	if err = errors.Join(
		checkDescribed(entries),
		checkDrift(committed, entries, opts.allowRemovals, !opts.check),
	); err != nil {
		return err
	}

	machine, err := renderCatalogue(entries)
	if err != nil {
		return err
	}

	human := renderReference(entries)

	if opts.check {
		return errors.Join(
			compareFile(opts.cataloguePath, machine),
			compareFile(opts.referencePath, human),
		)
	}

	if err = codegen.WriteFile(opts.cataloguePath, machine); err != nil {
		return err
	}

	if err = codegen.WriteFile(opts.referencePath, human); err != nil {
		return err
	}

	fmt.Fprintf(os.Stderr, "OK event-type set: %s (%d types)\n", opts.cataloguePath, len(entries))
	fmt.Fprintf(os.Stderr, "OK event-type reference: %s\n", opts.referencePath)

	return nil
}
